// Generates Zod validators + TS types from the JSON Schema exported by
// services/quant (ADR-0002). Do not edit src/generated/** by hand.
// Usage: node scripts/generate.mjs [--check]
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { jsonSchemaToZod } from "json-schema-to-zod";
import prettier from "prettier";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

const targets = [
  { schema: "strategy.schema.json", out: "strategy.ts", name: "strategySchema", type: "Strategy" },
  {
    schema: "backtest-result.schema.json",
    out: "backtest-result.ts",
    name: "backtestResultSchema",
    type: "BacktestResult",
  },
];

// Inline local "#/$defs/X" references (the schemas are non-recursive) so every
// nested object gets a real validator instead of z.any().
function inlineRefs(node, defs) {
  if (Array.isArray(node)) return node.map((n) => inlineRefs(n, defs));
  if (node === null || typeof node !== "object") return node;
  const { $ref, $defs: _defs, ...rest } = node;
  const out = {};
  for (const [k, v] of Object.entries(rest)) out[k] = inlineRefs(v, defs);
  if ($ref) {
    const name = $ref.replace("#/$defs/", "");
    if (!defs[name]) throw new Error(`unresolved $ref ${$ref}`);
    return { ...inlineRefs(defs[name], defs), ...out };
  }
  return out;
}

let stale = [];
await mkdir(join(root, "src/generated"), { recursive: true });
for (const t of targets) {
  const raw = JSON.parse(await readFile(join(root, "schema", t.schema), "utf8"));
  const schema = inlineRefs(raw, raw.$defs ?? {});
  const body = jsonSchemaToZod(schema, { name: t.name, module: "esm", type: t.type });
  const header =
    "// GENERATED by packages/shared/scripts/generate.mjs from schema/" +
    t.schema +
    ". Do not edit.\n/* eslint-disable */\n";
  const code = await prettier.format(header + body, { parser: "typescript", printWidth: 100 });
  const path = join(root, "src/generated", t.out);
  const current = await readFile(path, "utf8").catch(() => null);
  if (current !== code) {
    if (check) stale.push(t.out);
    else {
      await writeFile(path, code);
      console.log(`wrote ${path}`);
    }
  }
}
if (stale.length) {
  console.error(`stale generated files: ${stale.join(", ")}; run pnpm generate`);
  process.exit(1);
}
